/**
 * @name Parameter to socket operation flow
 * @description Function parameters flowing to socket operations could lead to SSRF or other network attacks
 * @kind path-problem
 * @problem.severity medium
 * @id py/parameter-to-socket
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.ApiGraphs

module ParamSocketConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof DataFlow::ParameterNode
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember(["socket", "connect", "connect_ex", "getaddrinfo"]).getACall() and
      sink = call
    ) or
    sink = API::moduleImport("asyncio").getMember(["open_connection", "start_server"]).getACall()
  }
}

module ParamSocketFlow = TaintTracking::Global<ParamSocketConfig>;
import ParamSocketFlow::PathGraph

from ParamSocketFlow::PathNode source, ParamSocketFlow::PathNode sink
where ParamSocketFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Function parameter flows to socket operation $@.", source.getNode(), "parameter"

/**
 * @name IP address injection via socket operations
 * @description User-controlled IP addresses flowing to socket operations without proper validation
 * @kind path-problem
 * @problem.severity medium
 * @id py/ip-injection
 * @tags security
 *        external/cwe/cwe-20
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module IPInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Check for socket operations with IP address parameters
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("socket").getMember("getaddrinfo").getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("socket").getMember(["connect", "connect_ex"]).getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("asyncio").getMember("open_connection").getACall() and
        sink = call.getArg(0)
      ) or
      (
        call = API::moduleImport("asyncio").getMember("start_server").getACall() and
        sink = call.getArg(0)
      )
    )
  }
}

module IPInjectionFlow = TaintTracking::Global<IPInjectionConfig>;
import IPInjectionFlow::PathGraph

from IPInjectionFlow::PathNode source, IPInjectionFlow::PathNode sink
where IPInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potentially unsafe IP address usage from $@.", source.getNode(), "user input"

/**
 * @name SSRF via IP address parsing to socket connection
 * @description User input flows to IP address parsing then to socket connections, potentially bypassing validation
 * @kind path-problem
 * @problem.severity high
 * @id py/ssrf-ip-chain
 * @tags security
 *        external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module IPtoSocketConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Sink: IP address parsing (potential validation bypass)
    exists(DataFlow::CallCfgNode call |
      (call = API::moduleImport("ipaddress").getMember(["IPv4Address", "IPv6Address"]).getACall() or
       call = API::moduleImport("ipaddress").getMember("ip_address").getACall()) and
      sink = call.getArg(0)
    ) or
    // Sink: Socket connection
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("socket").getMember("socket").getMember(["connect", "connect_ex"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module IPtoSocketFlow = TaintTracking::Global<IPtoSocketConfig>;
import IPtoSocketFlow::PathGraph

from IPtoSocketFlow::PathNode source, IPtoSocketFlow::PathNode sink
where IPtoSocketFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "SSRF chain: user input flows to $@.", source.getNode(), "IP/socket operation"

/**
 * @name User input flowing to ipaddress parsing without validation
 * @description Untrusted input directly flowing to ipaddress parsing can lead to validation bypass or DoS
 * @kind path-problem
 * @problem.severity high
 * @id py/ip-parsing-taint
 * @tags security
 *        external/cwe/cwe-20
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module IpParsingConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // Look for calls to ipaddress.IPv4Address, ipaddress.IPv6Address, ipaddress.ip_address
      call = API::moduleImport("ipaddress").getMember(["IPv4Address", "IPv6Address", "ip_address"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module IpParsingPath = TaintTracking::Global<IpParsingConfig>;
import IpParsingPath::PathGraph

from IpParsingPath::PathNode source, IpParsingPath::PathNode sink
where IpParsingPath::flowPath(source, sink)
select sink.getNode(), source, sink, "User input flows to ipaddress parsing without validation $@.", source.getNode(), "user input"
